if wantenter('CHAMBER OF NECROMANCER') then begin
              party.etc[1] := 1;
              Silent_Scroll;
              i := 0; j := 0;
              for k := 1 to 10 do begin
                 if k > 1 then
                    putimage(100+i*20,100+j*20,font^[map[x+i,y+j]],copyput);
                 i := random(9)-4; j := random(9)-4;
                 if (i=0) and (j=0) then j := -1;
                 putimage(100+i*20,100+j*20,chara^[50],andput);
                 putimage(100+i*20,100+j*20,chara^[22],orput);
                 delay(1000);
              end;
              Print(13,' 두말이 필요없다. 덤벼라 !!');
              PressAnyKey;
              enemynumber := 6;
              for i := 1 to 5 do joinenemy(i,63);
              joinenemy(6,72);
              displayenemies(TRUE);
              battlemode(TRUE);
              if party.etc[6] = 255 then exit;
              if party.etc[6] > 0 then begin
                 x := 25; y := 45;
                 scroll(TRUE);
                 exit;
              end;
              with party do begin
                 map := 26; xaxis := 25; yaxis := 15;
              end;
              load;
              scroll(FALSE);
              face := 5;
              for j := 4 downto 0 do begin
                 if j < 4 then
                    putimage(100,120+j*20,font^[map[x,y+j+1]],copyput);
                 putimage(100,100+j*20,chara^[33],andput);
                 putimage(100,100+j*20,chara^[5],orput);
                 delay(1000);
              end;
              for j := 16 to 19 do
              for i := 24 to 26 do map[i,j] := 16;
              scroll(TRUE);
           end

begin
              Clear;
              if y = 46 then begin
                 if wantexit then begin
                    with party do begin
                       xaxis := 25; yaxis := 45; map := 23;
                    end;
                    load;
                    scroll(TRUE);
                 end
                 else begin
                    dec(y); scroll(TRUE);
                 end;
              end;
              if y = 43 then begin
                 if party.etc[1] = 0 then begin
                    party.etc[1] := 1;
                    Silent_Scroll;
                 end;
                 Print(15,' 금속으로된 어떤 적이 나타났다.');
                 putimage(100,20,chara^[51],andput);
                 putimage(100,20,chara^[23],orput);
                 for j := 1 to 3 do begin
                    delay(2000);
                    for i := 0 to 9 do begin
                       if (i = 0) and (j > 1) then
                          putimage(100,(j-1)*20,font^[map[x,y+j-5]],copyput);
                       putimage(100,j*20,font^[map[x,y+j-5]],copyput);
                       putimage(100,(j+1)*20,font^[map[x,y+j-4]],copyput);
                       putimage(100,j*20+i*2,chara^[51],andput);
                       putimage(100,j*20+i*2,chara^[23],orput);
                    end;
                 end;
                 Clear;
                 Print(13,' 여기까지 잘도왔구나. 나의 임무는 너희 같은');
                 Print(13,'쓰레기들 때문에 Necromancer 님이 수고하시지');
                 Print(13,'않도록 미리 처단해 버리는 것이다.');
                 PressAnyKey;
                 enemynumber := 5;
                 for i := 1 to 4 do joinenemy(i,66);
                 joinenemy(5,71);
                 displayenemies(TRUE);
                 battlemode(FALSE);
                 if party.etc[6] = 255 then exit;
                 if party.etc[6] > 0 then begin
                    inc(y);
                    scroll(TRUE);
                    exit;
                 end;
                 for i := 24 to 27 do map[i,y] := 41;
                 Clear;
                 Print(15,' 당신이 적을 물리치자 조금후에 이상하리만큼');
                 Print(15,'편안한 기운이 일행을 감쌌다.');
                 PressAnyKey;
                 enemynumber := 2;
                 joinenemy(1,68); joinenemy(2,67);
                 displayenemies(TRUE);
                 Print(7,' 매우 수고하시는군요. '+player[1].name);
                 Print(7,' 당신이 Necromancer에게 가기전에 한 가지 일');
                 Print(7,'러 두고자 하오.');
                 Print(7,' 이곳에는 비밀스런 문이 두군데 있소. 지금은');
                 Print(7,'보이지가 않지만 양쪽의 벽을 살피다 보면  숨');
                 Print(7,'겨진 문 안에 레버가 각각 하나씩 있소.  그걸');
                 Print(7,'모두 작동시키면 용암의 중앙에서 Necromancer');
                 Print(7,'의 방으로 통하는 입구가 보일 것이오. 여기까');
                 Print(7,'지만 내가 알려줄 수가 있는 부분이오. 마지막');
                 Print(7,'으로 당신의 건투를 빌겠소.');
                 talk('');
                 for i := 1 to 6 do
                 if player[i].name <> '' then player[i].class := 10;
                 scroll(TRUE);
              end;
              if on(15,34) then begin
                 map[15,34] := 41;
                 for i := 11 to 14 do begin
                    map[i,33] := 24; map[i,35] := 26; map[i,34] := 42;
                 end;
                 map[14,33] := 17; map[14,35] := 18;
              end;
              if on(36,34) then begin
                 map[36,34] := 41;
                 for i := 37 to 40 do begin
                    map[i,33] := 24; map[i,35] := 26; map[i,34] := 42;
                 end;
                 map[37,33] := 19; map[37,35] := 22;
              end;
              if on(5,34) then begin
                 party.etc[45] := party.etc[45] or bit7;
                 Print(7,' 당신이 레버를 당기자  철컥하는 소리가 동굴');
                 Print(7,'에 울려 퍼졌다.');
                 if (party.etc[45] and bit7 > 0) and (party.etc[45] and bit8 > 0)
                 then begin
                    map[25,27] := 54; map[26,27] := 54;
                    Print(7,' 곧 이어 기계 작동하는 큰 소리가 들렸다.');
                 end;
                 PressAnyKey;
              end;
              if on(46,34) then begin
                 party.etc[45] := party.etc[45] or bit8;
                 Print(7,' 당신이 레버를 당기자  철컥하는 소리가 동굴');
                 Print(7,'에 울려 퍼졌다.');
                 if (party.etc[45] and bit7 > 0) and (party.etc[45] and bit8 > 0)
                 then begin
                    map[25,27] := 54; map[26,27] := 54;
                    Print(7,' 곧 이어 기계 작동하는 큰 소리가 들렸다.');
                 end;
                 PressAnyKey;
              end;
           end
